<script>(()=>{document.querySelectorAll('.blog-editor-form').forEach(form=>{const ed=form.querySelector('.rich-editor'),out=form.querySelector('.blog-body-html'),bar=form.querySelector('.editor-toolbar');if(!ed||!out||!bar)return;const preview=form.querySelector('.stamp-preview'),previewImg=form.querySelector('.stamp-preview-image'),previewBadge=form.querySelector('.stamp-preview-badge');const updateStamp=()=>{if(!previewBadge)return;const pos=form.querySelector('[name=stamp_position]')?.value||'top-right',rot=form.querySelector('[name=stamp_rotation]')?.value||'-5',op=form.querySelector('[name=stamp_opacity]')?.value||'.76';previewBadge.className='ai-image-stamp stamp-preview-badge stamp-'+pos;previewBadge.style.setProperty('--stamp-rot',rot+'deg');previewBadge.style.setProperty('--stamp-opacity',op)};form.querySelectorAll('[name=stamp_position],[name=stamp_rotation],[name=stamp_opacity]').forEach(x=>x.addEventListener('change',updateStamp));form.querySelectorAll('input[name=image_library]').forEach(x=>x.addEventListener('change',()=>{if(x.checked&&previewImg){const im=x.closest('.media-choice')?.querySelector('img');if(im)previewImg.src=im.src}updateStamp()}));const fileInput=form.querySelector('input[type=file][name=image]');if(fileInput)fileInput.addEventListener('change',()=>{const f=fileInput.files?.[0];if(f&&previewImg){const u=URL.createObjectURL(f);previewImg.onload=()=>URL.revokeObjectURL(u);previewImg.src=u}updateStamp()});updateStamp();try{document.execCommand('defaultParagraphSeparator',false,'p')}catch(e){}let saved=null;const save=()=>{const sel=window.getSelection();if(sel&&sel.rangeCount&&ed.contains(sel.anchorNode))saved=sel.getRangeAt(0).cloneRange()};const restore=()=>{ed.focus();if(saved){const sel=window.getSelection();sel.removeAllRanges();sel.addRange(saved)}};['mouseup','keyup','touchend'].forEach(ev=>ed.addEventListener(ev,save));bar.addEventListener('mousedown',e=>{if(e.target.closest('button'))e.preventDefault()});bar.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;restore();if(b.dataset.cmd){document.execCommand(b.dataset.cmd,false,null)}else if(b.dataset.block){document.execCommand('formatBlock',false,b.dataset.block)}else if(b.hasAttribute('data-link')){const u=prompt('Адреса посилання (https://… або /сторінка/):','https://');if(u){restore();const sel=window.getSelection();if(sel&&sel.rangeCount&&!sel.getRangeAt(0).collapsed)document.execCommand('createLink',false,u);else{const txt=prompt('Текст посилання:',u)||u;document.execCommand('insertHTML',false,'<a href="'+u.replace(/"/g,'&quot;')+'">'+txt.replace(/</g,'&lt;').replace(/>/g,'&gt;')+'</a>')}}save()}});bar.querySelectorAll('.blog-link-picker').forEach(p=>p.addEventListener('change',()=>{if(!p.value)return;restore();const sel=window.getSelection(),title=p.options[p.selectedIndex]?.dataset.title||p.options[p.selectedIndex]?.textContent||'допис';if(sel&&sel.rangeCount&&!sel.getRangeAt(0).collapsed)document.execCommand('createLink',false,p.value);else document.execCommand('insertHTML',false,'<a href="'+p.value+'">'+title.replace(/</g,'&lt;').replace(/>/g,'&gt;')+'</a>');p.value='';save()}));form.addEventListener('submit',e=>{out.value=ed.innerHTML.trim();if((ed.innerText||'').trim().length<40){e.preventDefault();alert('Текст статті надто короткий.');ed.focus()}})})})();</script>
